/* Study 21: synthetic body-only post editing. No API, uploads or saved drafts. */
(function(){
'use strict';
const E=id=>document.getElementById(id),T=window.RelaxeStudyTheme,config={appearance:'light',palette:'blue',text:'1',width:'390'};
const title='A quiet loop after the rain',dialog=E('post-dialog'),content=E('post-dialog-content');
let published='We took the lower loop after the rain. The sheltered sections were muddy, but the path was easy to follow.\n\nStarting early gave us a quiet morning and time to stop at the viewpoint.',presentation='inline',fixture='ready',closed=true,pending=null,recover=false,origin=null,allowNavigation=false;
const blocked=()=>['guest','not-author','nontext','with-media'].includes(fixture);
const message=(id,text)=>{E(id).textContent=text;E(id).hidden=!text};
function theme(){const settings={foundation:'selected',...config},direction=T.directions[0],phone=E('post-phone');for(const [key,value]of Object.entries(T.tokens(direction,settings)))phone.style.setProperty(key,value);T.setStyleAttributes(phone,direction,settings);phone.style.setProperty('--w',config.width+'px');phone.style.setProperty('--h',({360:800,390:844,600:960,720:480}[config.width])+'px');phone.dataset.largeText=String(+config.text>=2);window.RelaxeShell?.setContext({account:fixture==='guest'?'guest':'weekendreader',subreddit:'hiking',...config})}
function sync(){const inline=presentation==='inline',busy=Boolean(pending),editor=E('post-editor'),home=inline?E('post-inline-slot'):E('post-editor-home'),actions=E('post-actions'),close=E('post-close');E('post-phone').dataset.presentation=presentation;E('post-screen-bar').hidden=inline;E('post-thread-bar').hidden=!inline;E('post-original-body').hidden=!inline;E('post-title-label').hidden=inline;E('post-open-inline').hidden=!inline||blocked();E('post-open-inline').disabled=busy;E('post-open-inline').setAttribute('aria-expanded',String(!closed));E('post-inline-bar').hidden=!inline;if(editor.parentElement!==home)home.append(editor);if(inline){if(actions.parentElement!==E('post-inline-bar'))E('post-inline-bar').append(actions,close)}else if(actions.parentElement!==E('post-screen-bar')){E('post-screen-bar').insertBefore(close,E('post-screen-bar').querySelector('h2'));E('post-screen-bar').append(actions)}E('post-edit-form').hidden=closed&&!inline;editor.hidden=closed;E('post-closed').hidden=!closed||inline;E('post-body').disabled=busy||blocked();E('post-save').disabled=closed||busy||blocked()||E('post-body').value===published;E('post-save').textContent=busy?'Saving…':'Save changes';E('post-preview').disabled=closed||busy||blocked();E('post-close').disabled=closed;E('post-reopen').disabled=blocked();E('post-fixture').disabled=busy;E('post-presentation').disabled=busy;for(const b of E('post-editor').querySelectorAll('.format-bar button'))b.disabled=closed||busy||blocked();const notice=busy?'Saving changes…':fixture==='guest'?'Sign in to edit your post.':fixture==='not-author'?'You can edit only your own posts.':fixture==='nontext'?'This post type can’t be edited.':fixture==='with-media'?'This post can’t be edited because it contains embedded images.':'';message('post-notice',notice);E('post-meta').textContent='r/hiking · u/'+(fixture==='not-author'?'trailnotes':'weekendreader');message('post-inline-status',inline&&closed?E('post-result').textContent:'');theme()}
function paragraph(node,text){const p=document.createElement('p');p.textContent=text;node.append(p);return p}
function action(node,label,callback,primary=false){const b=document.createElement('button');b.type='button';b.textContent=label;if(primary)b.className='primary';b.addEventListener('click',callback);node.append(b);return b}
function show(title,build){if(!dialog.open)origin=document.activeElement;E('post-dialog-title').textContent=title;content.replaceChildren();build(content);dialog.showModal();E('post-dialog-close').focus()}
function inlineText(node,text){const pattern=/\*\*([^*]+)\*\*|\*([^*]+)\*|`([^`]+)`|\[([^\]]+)\]\(([^)]+)\)/g;let last=0,m;while((m=pattern.exec(text))){node.append(document.createTextNode(text.slice(last,m.index)));const el=document.createElement(m[1]?'strong':m[2]?'em':m[3]?'code':'span');el.textContent=m[1]||m[2]||m[3]||m[4];if(m[4])el.append(document.createTextNode(' ('+m[5]+')'));node.append(el);last=pattern.lastIndex}node.append(document.createTextNode(text.slice(last)))}
function renderBody(node,text){node.replaceChildren();for(const line of text.split('\n')){const p=document.createElement(line.startsWith('> ')?'blockquote':'p');inlineText(p,line.startsWith('> ')?line.slice(2):line);node.append(p)}}
function focusEditor(){E('post-body').focus({preventScroll:true});E('post-editor').scrollIntoView({block:'nearest'})}
function focusClosed(){(presentation==='inline'?E('post-open-inline'):E('post-reopen')).focus({preventScroll:true})}
function open(){if(blocked())return;if(!recover&&!pending)E('post-body').value=published;recover=false;closed=false;message('post-error','');sync();focusEditor()}
function leave(next){if(pending){show('Leave while saving?',node=>{paragraph(node,'Your post is still being saved. Leaving may not stop the update.');const buttons=document.createElement('div');buttons.className='dialog-actions';action(buttons,'Keep editing',()=>dialog.close());action(buttons,'Leave editor',()=>{dialog.close();next('Saving was in progress when you left.')});node.append(buttons)});return}if(E('post-body').value===published){next('No changes kept.');return}show('Discard changes?',node=>{paragraph(node,'Your changes to this post body will be discarded.');const buttons=document.createElement('div');buttons.className='dialog-actions';action(buttons,'Keep editing',()=>dialog.close());action(buttons,'Discard changes',()=>{E('post-body').value=published;dialog.close();next('Changes discarded.')});node.append(buttons)})}
function close(){leave(copy=>{closed=true;E('post-result').textContent=copy;sync();focusClosed()})}
function preview(){show('Post preview',node=>{node.className='dialog-preview';const h=document.createElement('h4');h.textContent=title;node.append(h);paragraph(node,'r/hiking · u/weekendreader');const body=document.createElement('div');renderBody(body,E('post-body').value);node.append(body);if(!E('post-body').value)paragraph(node,'Empty post body.');paragraph(node,'Preview only. Nothing was sent.')})}
function format(kind){const f=E('post-body'),text=f.value.slice(f.selectionStart,f.selectionEnd)||'text',pairs={bold:['**','**'],italic:['*','*'],link:['[','](https://example.com)'],strike:['~~','~~'],superscript:['^(',')'],heading:['## ',''],numbered:['1. ',''],list:['- ',''],spoiler:['>!','!<'],quote:['> ',''],code:['```\n','\n```']};if(!pairs[kind])return;const [before,after]=pairs[kind];if(dialog.open){origin=f;dialog.close()}f.setRangeText(before+text+after,f.selectionStart,f.selectionEnd,'select');message('post-error','');sync();focusEditor()}
for(const [id,key]of [['post-appearance','appearance'],['post-palette','palette'],['post-scale','text'],['post-width','width']])E(id).addEventListener('change',event=>{config[key]=event.target.value;theme()});E('post-presentation').addEventListener('change',event=>{presentation=event.target.value;sync()});E('post-fixture').addEventListener('change',event=>{fixture=event.target.value;message('post-error','');sync()});E('post-body').addEventListener('input',()=>{message('post-error','');sync()});for(const b of document.querySelectorAll('[data-format]'))b.addEventListener('click',()=>format(b.dataset.format));E('post-more').addEventListener('click',()=>show('Formatting',node=>{const buttons=document.createElement('div');buttons.className='post-format-options';for(const [kind,label]of [['strike','Strikethrough'],['superscript','Superscript'],['heading','Heading'],['numbered','Numbered list'],['list','Bulleted list'],['spoiler','Spoiler'],['quote','Quote'],['code','Code block']])action(buttons,label,()=>format(kind));node.append(buttons)}));E('post-preview').addEventListener('click',preview);E('post-close').addEventListener('click',close);E('post-reopen').addEventListener('click',open);E('post-open-inline').addEventListener('click',()=>{if(closed)open();else focusEditor()});
E('post-edit-form').addEventListener('submit',event=>{event.preventDefault();if(E('post-save').disabled)return;const task={body:E('post-body').value,fail:fixture==='save-error'};pending=task;message('post-error','');sync();setTimeout(()=>{if(pending!==task)return;pending=null;if(dialog.open&&E('post-dialog-title').textContent==='Leave while saving?')dialog.close();if(task.fail){recover=closed;if(closed)E('post-result').textContent='Couldn’t save changes. Reopen the editor to recover your writing.';message('post-error','Couldn’t save changes. Your writing is kept. Try again.')}else{published=task.body;renderBody(E('post-original-body'),published);closed=true;E('post-result').textContent='Post updated.'}sync();if(closed)focusClosed()},650)});
E('post-dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{content.className='';if(!E('post-editor').contains(document.activeElement)&&origin?.isConnected&&!origin.disabled)origin.focus({preventScroll:true})});dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=[...dialog.querySelectorAll('button,a,input,textarea,select')].filter(el=>!el.disabled&&!el.hidden),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!dialog.open&&!closed){event.preventDefault();close()}});document.addEventListener('click',event=>{const b=event.target.closest('.shared-shell-nav [data-destination]');if(!b||b.dataset.destination==='search'||closed)return;if(allowNavigation){allowNavigation=false;return}if(E('post-body').value===published&&!pending)return;event.preventDefault();event.stopImmediatePropagation();leave(()=>{allowNavigation=true;b.click()})},true);
E('post-close').innerHTML=T.icon('close');E('post-dialog-close').innerHTML=T.icon('close');E('post-more').innerHTML=T.icon('more');const params=new URLSearchParams(location.search);if(params.get('style')==='screen'){presentation='screen';closed=false}E('post-presentation').value=presentation;E('post-body').value=published;renderBody(E('post-original-body'),published);sync();document.addEventListener('relaxe-shell-ready',theme,{once:true});
})();
